Q: How to smoothly rebuilds the AVComposition A: <p>I do NOT believe it is possible to seamlessly transition a mutating <code>trim</code> function while calling the <code>AVPlayer.replaceCurrentItem (_: )</code> function.
This is my first time dealing with the <code>AVKit</code> Library... I mean Module.
I looked everywhere for a way to publish the mutating state of the <code>AVMutableComposition</code> class without calling <code>.replaceCurrentItem (_: )</code> to no avail.</p>
<p>I do believe that the Player's <code>CurrentItem</code> is played from a private cache, so updating any objects used in its creation won't affect <code>VideoPlayer</code> directly.
Even if a handle were left to that object. I tested this extensively. The best I could do was a <code>trim</code> that was not reflected in the controls ( time remaining and slider adjustment. )</p>
<p>If were going to keep trying, I would explore the older Appkit functionalities next.
Theres just so much in those methods I know nothing about.</p>
<p>With the help of @Andrew's answer (here) [ https://stackoverflow.com/a/73488268/22165242 ], I wrapped the <code>AVPlayer</code> in a <code>NSViewRepresentable</code> which allowed me to toggle off the <code>VideoPlayer</code>'s controls.
After which I implemented a few controls of my own. These controls can be updated through the <code>ObservableObject</code> conformance of my <code>AVPlayer</code>sub-class , and allow me to bypass <code>.replaceCurrentItem (_: )</code> in publishing changes to the UI.</p>
<p>4 of the objects in the code below are altered versions of your <code>.buildComposition(_:)</code> function. They're essentially doing the same thing. I concentrated on practicing Swift 6 while I writing them.
There have been a lot of great SO publications on <code>Sendable</code> and <code>nonisolated</code> in the past months which I am thankful for. I had fun learning this module. Thank you for posting your challenge.</p>
<pre><code>/// Video Player and Controls
struct ProjectEditor: View {

  private let url: URL
  @StateObject private var player = MyPlayer()

  init ( url: URL ) { self.url = url }


  var body: some View {
    VStack {
      MyVideoView ( player: player )
        .task { try? await player.build ( url: url ) }

      HStack {
        playToggle
        Slider.init ( value: player.sliderBinding , in: player.currentRange , label: { Text( &quot;&quot; ) } , minimumValueLabel: { player.currentTime().seconds.monoSpacedView  } , maximumValueLabel: { player.currentRange.upperBound.monoSpacedView } )
        Button ( &quot;Trim&quot; , action: { player.trimFront ( by: 2 ) } )
      }
      .background ( .blue , in: RoundedRectangle ( cornerRadius: 25 ).stroke( lineWidth: 5) )
      .padding()
      .lineLimit(1)
      .monospaced()
    }
  }
  var playToggle: some View {
    let isPlaying = player.timeControlStatus == .playing
    return Button ( isPlaying ? &quot;Pause&quot; : &quot;Play &quot; , systemImage: isPlaying ? &quot;pause&quot; : &quot;play&quot; , action: { isPlaying ? player.pause() : player.play() } )
  }
}

extension Double {
  var monoSpacedView: Text {
    Text ( self.formatted ( .number.precision ( .fractionLength ( 1 ) ) ).description ).font ( .headline ) // I hate the way this reads and writes
  }
}

/// Base struct. Collects data from URL.mp4 and is passes it up the ladder.
/// Is not kept and stored but could potentially be useful for may other things later.
struct AssetData {
  let asset      : AVAsset
  var startTime  : CMTime = .zero
  var duration   : CMTime
  var videoSource: AVAssetTrack
  var audioSource: AVAssetTrack
  var timeRange  : CMTimeRange { CMTimeRange ( start: startTime , duration: duration ) }

  init ( url: URL ) async throws {
    self.asset = AVURLAsset ( url: url )
    self.duration = try await asset.load ( .duration )
    guard let videoSource = try await asset.loadTracks ( withMediaType: .video ).first else { throw AVError ( .noSourceTrack ) }
    guard let audioSource = try await asset.loadTracks ( withMediaType: .audio ).first else { throw AVError ( .noSourceTrack ) }
    self.videoSource = videoSource
    self.audioSource = audioSource
  }
}


class MutableComposition: AVMutableComposition {

  private nonisolated override init() { super.init() }

  convenience init ( data: AssetData ) throws {
    self.init ()
    guard let video = addMutableTrack ( withMediaType: .video , preferredTrackID: kCMPersistentTrackID_Invalid ) else { throw AVError ( .noSourceTrack ) }
    guard let audio = addMutableTrack ( withMediaType: .audio , preferredTrackID: kCMPersistentTrackID_Invalid ) else { throw AVError ( .noSourceTrack ) }
    try video.insertTimeRange ( data.timeRange , of: data.videoSource , at: .zero )
    try audio.insertTimeRange ( data.timeRange , of: data.audioSource , at: .zero )
  }
}

class MutableVideoComposition: AVMutableVideoComposition , @unchecked Sendable {

  nonisolated override init() { super.init() }

  convenience init ( data: AssetData ) async throws {
    self.init()
    self.frameDuration = CMTime ( value: 1 , timescale: 30 )
    self.renderSize = try await data.videoSource.load ( .naturalSize )
    self.instructions = [ CompositorInstruction ( timeRange: data.timeRange , requiredSourceTrackIDs: [ NSNumber ( value: data.videoSource.trackID ) ] ) ]
    self.customVideoCompositorClass = CustomVideoCompositor.self
  }
}

class MyPlayer: AVPlayer , ObservableObject {

  private var mutableComposition      = MutableComposition()
  private var mutableVideoComposition = MutableVideoComposition()
  private var playerItem: AVPlayerItem?

  @Published var currentRange: ClosedRange &lt; Double &gt; = 0...1
  @Published var currentTime : Double = .zero


  nonisolated         override init (                              ) { super.init (                         ) }
  nonisolated private override init (    url     :       URL       ) { super.init (     url    :    url     ) }
  nonisolated private override init ( playerItem :  AVPlayerItem?  ) { super.init ( playerItem : playerItem ) }



  func build ( url: URL ) async throws {
    let data = try await AssetData ( url: url )
    guard let mutableComposition      = try?       MutableComposition      ( data: data ) else { throw AVError ( .invalidVideoComposition ) }
    guard let mutableVideoComposition = try? await MutableVideoComposition ( data: data ) else { throw AVError ( .videoCompositorFailed   ) }

    self.mutableComposition = mutableComposition
    self.mutableVideoComposition = mutableVideoComposition

    self.playerItem = AVPlayerItem ( asset: mutableComposition )
    self.playerItem?.videoComposition = mutableVideoComposition
    self.replaceCurrentItem ( with: playerItem )
    self.currentRange = data.timeRange.asDoubleRange
    self.attachTimeObserver()
  }

  func attachTimeObserver() {
    self.addPeriodicTimeObserver ( forInterval: CMTime ( seconds: 0.1 , preferredTimescale: 600 ) , queue: .main ) { [ weak self ] time in
      Task { @MainActor in self?.currentTime = time.seconds }
    }
  }
}

extension MyPlayer {
  func trimFront ( by seconds: Double ) {
    self.pause()
    let trimRange = CMTimeRange ( start: .zero , duration: .init ( seconds: seconds , preferredTimescale: 600 ) )
    self.mutableComposition.removeTimeRange ( trimRange )
    self.currentRange = CMTimeRange ( start: .zero , end: mutableComposition.duration ).asDoubleRange
    self.seek ( to: .zero , toleranceBefore: .zero , toleranceAfter: .zero )
    self.play()
  }
}

extension CMTimeRange {
  var asDoubleRange: ClosedRange &lt; Double &gt; { self.start.seconds...self.duration.seconds }
}
extension MyPlayer {
  var sliderBinding: Binding &lt; Double &gt; {
    Binding (
      get: { return self.currentTime().seconds } ,
      set: { self.pause() ; self.seek ( to: CMTime ( value: CMTimeValue ( $0 * 600 ) , timescale: 600 ) , toleranceBefore: .zero , toleranceAfter: .zero ) }
    )
  }
}

// Used to turn off embedded `VideoPlayer` Controls
/// Copied from Author: Andrew
/// StackOverflow Question:  &quot;Playback controls in swiftui&quot;
/// https://stackoverflow.com/a/73488268/22165242
/// Publication Date: Aug 25, 2022

fileprivate struct MyVideoView : NSViewRepresentable {
  var player : AVPlayer
  func makeNSView ( context: Context ) -&gt; AVPlayerView {
    let view = AVPlayerView()
    view.controlsStyle = .none
    view.player = player
    return view
  }
  func updateNSView(_ nsView: AVPlayerView, context: Context) { }
}
</code></pre>
